class Animal:
    def __init__(self, name):
        self.name = name

    def speak(self):
        return "..."


class Dog(Animal):
    def speak(self):
        return f"{self.name}: 汪"


print(Dog("旺财").speak())
print(Animal("无名").speak())
print(isinstance(Dog("旺财"), Animal))

class Base:
    def __init__(self, name):
        self.name = name

    def describe(self):
        return f"Base({self.name})"


class Sub(Base):
    def __init__(self, name, extra):
        super().__init__(name)
        self.extra = extra

    def describe(self):
        return super().describe() + f" + {self.extra}"


print(Sub("x", "y").describe())

class Engine:
    def start(self):
        return "引擎启动"


class Car:
    def __init__(self):
        self.engine = Engine()

    def start(self):
        return self.engine.start()


print(Car().start())
print(isinstance(Car(), Engine))
